// The extension was named Blueprint Visual Scripting before NodeCraft. What it wrote under that name
// is still its own: generated files are recognized by their header (so compiles write over them and
// the map shows their graphs), and a build block it added is found and given the new marker, not
// added a second time.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generatedFrom, isGeneratedSupport } from '../../src/core/codemap/generated';
import { hasBlock, withBlock } from '../../src/core/output-plan';
import { CMAKE_BLOCK } from '../../src/core/languages/cpp';
import { RUST_BLOCK } from '../../src/core/languages/rust';

test('a file generated under either name is recognized by its header', () => {
  assert.equal(generatedFrom('// Generated by NodeCraft from Main.vgraph.\n'), 'Main.vgraph');
  assert.equal(generatedFrom('// Generated by Blueprint Visual Scripting from Main.vgraph.\n'), 'Main.vgraph');
  assert.equal(generatedFrom('// Code generated by Blueprint Visual Scripting from main.vgraph. DO NOT EDIT.\n'), 'main.vgraph');
  assert.equal(generatedFrom('# Generated by Something Else from Main.vgraph.\n'), undefined);
  assert.ok(isGeneratedSupport('vgraph_runtime.rs', '// Generated by Blueprint Visual Scripting: support code for the Rust generated from graphs.\n'));
});

test('a build block added under the former name gets the new marker, once', () => {
  const block = { ...CMAKE_BLOCK, text: 'include(vgraph.cmake)' };
  const former = ['project(app)', '# vgraph:begin (managed by Blueprint Visual Scripting)', 'include(old.cmake)', '# vgraph:end', 'add_executable(app main.cpp)', ''].join('\n');
  const updated = withBlock(former, block);
  assert.equal(updated, ['project(app)', '# vgraph:begin (managed by NodeCraft)', 'include(vgraph.cmake)', '# vgraph:end', 'add_executable(app main.cpp)', ''].join('\n'));
  assert.ok(hasBlock(updated, block));
  assert.ok(!hasBlock(former, block), 'the old marker counts as a change to make');
  const crlf = former.replace(/\n/g, '\r\n');
  assert.equal(withBlock(crlf, block), updated.replace(/\n/g, '\r\n'), 'line endings kept');
  const rust = '// vgraph:begin (managed by Blueprint Visual Scripting)\nmod old;\n// vgraph:end\n';
  assert.equal(withBlock(rust, { ...RUST_BLOCK, text: 'mod main_vgraph;' }), '// vgraph:begin (managed by NodeCraft)\nmod main_vgraph;\n// vgraph:end\n');
});
